#include <bits/stdc++.h>
using namespace std;
const int MODUL = 1e9 + 7;
int p, k;

int fastExponentiation(int base, int exp)
{
    if (exp == 1) return base;
    int half_exp = fastExponentiation(base, exp / 2);
    long long res = (1LL * half_exp * half_exp) % MODUL;
    if (exp % 2 == 0) return (int)res;
    return (int)((res * base) % MODUL);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    cin >> p >> k;

    if (k == 0)
    {
        cout << fastExponentiation(p, p - 1);
        return 0;
    }

    if (k == 1)
    {
        cout << fastExponentiation(p, p);
        return 0;
    }

    int count_m = 1;
    int t_value = k;
    while (true)
    {
        count_m++;
        t_value = (1LL * t_value * k) % p;
        if (t_value == 1)
        {
            cout << fastExponentiation(p, (p - 1) / count_m);
            return 0;
        }
    }

    return 0;
}
